import json
import math

# Load computed stats and chart data
with open('/app/output/computed_stats.json') as f:
    stats = json.load(f)
with open('/app/output/chart_data.json') as f:
    chart_data = json.load(f)

# Prepare chart data points
dates = [d['date'] for d in chart_data]
prices = [d['price'] for d in chart_data]

# Decade colors and data for charts
decade_colors = {
    '1970s': '#e74c3c',
    '1980s': '#e67e22', 
    '1990s': '#f1c40f',
    '2000s': '#2ecc71',
    '2010s': '#3498db',
    '2020s': '#9b59b6'
}

# Compute MoM changes for volatility chart
mom_dates = dates[1:]
mom_abs_changes = [round(prices[i] - prices[i-1], 2) for i in range(1, len(prices))]
mom_pct_changes = [round(((prices[i] - prices[i-1]) / prices[i-1]) * 100, 2) if prices[i-1] != 0 else 0 for i in range(1, len(prices))]

# Rolling 12-month volatility (std of monthly returns)
rolling_vol = []
for i in range(11, len(mom_pct_changes)):
    window = mom_pct_changes[i-11:i+1]
    mean_r = sum(window) / len(window)
    vol = math.sqrt(sum((r - mean_r)**2 for r in window) / len(window))
    rolling_vol.append(round(vol, 2))

rolling_vol_dates = mom_dates[11:]

# Decade bar chart data
dec_labels = list(stats['decade_stats'].keys())
dec_means = [round(stats['decade_stats'][d]['mean'], 2) for d in dec_labels]
dec_stds = [round(stats['decade_stats'][d]['std'], 2) for d in dec_labels]
